+    TrustManager[] buildTrustManagers() throws GeneralSecurityException, IOException {
+        var configurationCount = Stream.of(
+            this.certificateAuthorities,
+            this.trustStoreFile,
+            this.serverCertificate,
+            this.serverKeyStoreFile
