+                        hashTerm(term, hashes);
+                        for (int hash : hashes) {
+                            hash = hash % bloomFilterSize;
+                            final int pos = hash >> 3;
+                            final int mask = 1 << (hash & 7);
+                            final byte val = (byte) (buffer.get(pos) | mask);
+                            buffer.set(pos, val);
